'use client';
// Generated by APIX. Shows the agent vault's limits and spending.
import { useEffect, useState } from 'react';

interface Status {
  vaultId: string;
  network: string;
  paused: boolean;
  policy: { per_tx_limit: string; daily_limit: string };
  spent_in_window: string;
  available_balance: string;
  pending_requests: number;
  allowlist: string[];
  error?: string;
}

// NEAR with up to 5 decimals, from a yoctoNEAR string (no bigint literals: ES2017 target)
const near = (yocto: string) => (Number(BigInt(yocto) / BigInt('10000000000000000000')) / 1e5).toString();

export function AgentVaultStatus({ refreshMs = 15000 }: { refreshMs?: number }) {
  const [status, setStatus] = useState<Status | null>(null);

  useEffect(() => {
    let alive = true;
    const load = () => fetch('/api/agent/vault').then(r => r.json()).then(s => alive && setStatus(s)).catch(() => undefined);
    load();
    const timer = setInterval(load, refreshMs);
    return () => { alive = false; clearInterval(timer); };
  }, [refreshMs]);

  if (!status) return <div>Loading vault…</div>;
  if (status.error) return <div>Vault unavailable: {status.error}</div>;

  const spent = Number(near(status.spent_in_window));
  const daily = Number(near(status.policy.daily_limit));
  const explorer = status.network === 'mainnet' ? 'https://nearblocks.io' : 'https://testnet.nearblocks.io';

  return (
    <section style={{ border: '1px solid #ddd', borderRadius: 8, padding: 16, maxWidth: 420, fontFamily: 'system-ui' }}>
      <h3 style={{ margin: 0 }}>Agent vault {status.paused ? '⏸ paused' : '● active'}</h3>
      <p style={{ margin: '4px 0 12px', fontSize: 13 }}>
        <a href={`${explorer}/address/${status.vaultId}`} target="_blank" rel="noreferrer">{status.vaultId}</a>
      </p>
      <div>Spent today: {spent} / {daily} NEAR</div>
      <div style={{ background: '#eee', height: 6, borderRadius: 3, margin: '6px 0 12px' }}>
        <div style={{ width: `${Math.min(100, (spent / daily) * 100)}%`, height: 6, borderRadius: 3, background: '#2b7' }} />
      </div>
      <div>Max per payment: {near(status.policy.per_tx_limit)} NEAR</div>
      <div>Available: {near(status.available_balance)} NEAR</div>
      <div>Waiting for approval: {status.pending_requests}</div>
      <div style={{ fontSize: 13, marginTop: 8 }}>Can pay: {status.allowlist.join(', ')}</div>
    </section>
  );
}
